    "tip_load_title": "របៀបប៉ាន់ស្មានថាមពលកំពូល",
    "tip_load_body": "បូកថាមពលឧបករណ៍ដែលប្រើក្នុងពេលដំណាលគ្នា៖<br>· ម៉ាស៊ីនត្រជាក់ 1HP ប្រហែល 1000W<br>· ម៉ាស៊ីនត្រជាក់ 2HP ប្រហែល 2000W<br>· កុំព្យូទ័រ (~200W) + ទូទឹកកកតូច (~200W) + អំពូល និងកង្ហារ (~200W) + ទូរទស្សន៍ (~200W)",
    "tip_load_house_title": "របៀបប៉ាន់ស្មានថាមពលកំពូលសម្រាប់ផ្ទះ",
    "tip_load_house_body": "បូកថាមពលឧបករណ៍ដែលអាចដំណើរការពេលតែមួយ៖<br>· ម៉ាស៊ីនត្រជាក់ 1HP ≈ 1000W, 1.5HP ≈ 1300W, 2HP ≈ 1800W (ម៉ាស៊ីន inverter មានកំពូលពេលចាប់ផ្តើមខ្ពស់ជាង)<br>· ម៉ាស៊ីនកម្តៅទឹក ≈ 2000W (ប្រភេទកម្តៅភ្លាមៗ ≈ 6000W ធម្មតាមិនស័ក្តិសមសម្រាប់បម្រុង off-grid)<br>· ទូទឹកកក ≈ 150–250W, ទូរទស្សន៍ ≈ 100–200W, អំពូល LED ≈ 10–20W/គ្រាប់, កង្ហារ ≈ 50W<br>· រាប់តែឧបករណ៍ដែលប្រើពេលតែមួយ; ពេលយប់ជាធម្មតា ម៉ាស៊ីនត្រជាក់ + ទូទឹកកក + អំពូល, ពេលថ្ងៃបន្ថែមទូរទស្សន៍ ។ល។<br>· បញ្ជីខាងលើបានបំពេញតម្លៃធម្មតារួចហើយ — សូមកែចំនួន និងថាមពលតាមទីតាំងពិត។",
    "tip_load_supermarket_title": "របៀបប៉ាន់ស្មានថាមពលកំពូលសម្រាប់ផ្សារទំនើប / ហាង",
    "tip_load_supermarket_body": "ទូទឹកកក និងភ្លើងបំភ្លឺជាចំណុចសំខាន់ ហើយជាធម្មតាដំណើរការ 24 ម៉ោង៖<br>· ទូទឹកកកដេក/ឈរ ≈ 300–500W/គ្រឿង, ទូតាំងបង្ហាញ ≈ 200–400W/គ្រឿង — បូកតាមចំនួន<br>· ភ្លើងតាមធ្នើ/ច្រកដើរ ជាធម្មតា 8–15W/ម៉ែត្រ; ខ្សែភ្លើងធ្នើធម្មតា ≈ 80W។ បូកភ្លើងទាំងហាងតាមចំនួនដៃតាប៉េ (ឧ. 10 × 18W ≈ 180W)<br>· ការបង់ប្រាក់ (កុំព្យូទ័រ + ម៉ាស៊ីនព្រីន + ថតលុយ) ≈ 100–200W<br>· ម៉ាស៊ីនត្រជាក់គិតតាមម៉ោងបើកហាង, 1HP ≈ 1000W<br>· ទូទឹកកក និងភ្លើងដែលត្រូវបន្តដំណើរការពេលយប់ គួរកំណត់ជាបន្ទុកសំខាន់។",
    "tip_load_resort_title": "របៀបប៉ាន់ស្មានថាមពលកំពូលសម្រាប់រមណីយដ្ឋាន / សណ្ឋាគារ",
    "tip_load_resort_body": "គុណតាមចំនួនបន្ទប់ បន្ទាប់មកបូកឧបករណ៍រួម៖<br>· ក្នុងមួយបន្ទប់: ម៉ាស៊ីនត្រជាក់ 1HP ≈ 1000W (1.5HP ≈ 1300W) + ភ្លើង 100–200W + ទូរទស្សន៍ 100W + ម៉ាស៊ីនកម្តៅទឹក 1500–2000W<br>· តំបន់រួម: ភ្លើងច្រកដើរ/សាលធំ បូកតាមចំនួនគ្រឿង, ម៉ាស៊ីនបូមទឹក ≈ 750W, ម៉ាស៊ីនបូមស្រះ ≈ 1100W<br>· មិនត្រូវគិតថាបន្ទប់ទាំងអស់ប្រើពេលតែមួយទេ — ប្រើអត្រាស្នាក់ 60%–80% និងបញ្ចេញម៉ោងបូមទឹកខុសពីម៉ាស៊ីនត្រជាក់<br>· បន្ទប់ភ្ញៀវ និងម៉ាស៊ីនបូមទឹកដែលត្រូវការពេលអស់ភ្លើង គួរកំណត់ជាបន្ទុកសំខាន់; ម៉ាស៊ីនបូមស្រះអាចនៅខាង grid។",
    "tip_load_cafe_title": "របៀបប៉ាន់ស្មានថាមពលកំពូលសម្រាប់ហាងកាហ្វេ / ភោជនីយដ្ឋាន",
    "tip_load_cafe_body": "ហាងកាហ្វេ/ភោជនីយដ្ឋានមិនមានអំពូលតុប្រភេទផ្ទះទេ; បន្ទុកសំខាន់គឺឧបករណ៍កម្តៅ និងឧបករណ៍ត្រជាក់៖<br>· ម៉ាស៊ីនកាហ្វេ 1500–3000W (ប្រើរយៈពេលខ្លី តែកំពូលខ្ពស់ — ជាធម្មតាដាក់ខាង grid ដើម្បីឱ្យភ្លើងសាធារណៈទ្រាំ)<br>· ម៉ាស៊ីនធ្វើទឹកកក ≈ 800W, ទូទឹកកក/ទូត្រជាក់ 200–400W/គ្រឿង<br>· ចង្ក្រានអគ្គិសនី/ឡអគ្គិសនី 2000–4000W/គ្រឿង; បើហាងមានការដឹកជញ្ជូនច្រើន និងប្រើស្ទើរតែពេញមួយថ្ងៃ សូមបូកតាមចំនួនដែលប្រើពេលតែមួយ<br>· ភ្លើងបំភ្លឺតាមចំនួនអំពូលព្យួរ/spot ជាធម្មតា 300–600W<br>· ម៉ាស៊ីនត្រជាក់ពាណិជ្ជកម្ម 1.5HP ≈ 1300W/គ្រឿង គិតតាមម៉ោងបើកហាង<br>· មានតែឧបករណ៍ដែលមិនអាចឈប់ពេលអស់ភ្លើង (ឧ. ម៉ាស៊ីនកាហ្វេដែលប្រើស្ទើរតែពេញមួយថ្ងៃ ឬទូត្រជាក់) ទេ ដែលគួរកំណត់ជាបន្ទុកសំខាន់។",
    "tip_strategy_title": "ការពន្យល់យុទ្ធសាស្ត្រទាំងបី",
    "tip_strategy_body": "ម៉ោងពន្លឺព្រះអាទិត្យជាមធ្យមប្រចាំឆ្នាំ ~4.5 ម៉ោង។ រដូវវស្សាជាមធ្យមត្រឹម ~3 ម៉ោង អាក្រក់បំផុត ~2 ម៉ោង។ រដូវប្រាំងជាមធ្យម ~6 ម៉ោង ល្អបំផុត ~7 ម៉ោង។<br><br><b>ជម្រើស 1</b> — គណនាតាម 6 ម៉ោង: គ្រប់គ្រាន់នៅរដូវប្រាំង ខ្វះខ្លាំងនៅរដូវវស្សា ROI ខ្ពស់បំផុត។<br><b>ជម្រើស 2</b> — គណនាតាម 4.5 ម៉ោង: មានលើសនៅរដូវប្រាំង ខ្វះបន្តិចនៅរដូវវស្សា។ លំនាំដើម និងណែនាំ។<br><b>ជម្រើស 3</b> — គណនាតាម 3 ម៉ោង: លើសច្រើននៅរដូវប្រាំង គ្រប់គ្រាន់នៅរដូវវស្សា ROI ទាបបំផុត។",
