    "got_it": "Got it",
    "tip_load_title": "How to estimate peak power",
    "tip_load_body": "Add up the power of all devices running at the same time:<br>· 1HP air conditioner: ~1000W peak<br>· 2HP air conditioner: ~2000W peak<br>· One computer (~200W) + one small fridge (~200W) + a few lights and a fan (~200W) + one TV (~200W)",
    "tip_load_house_title": "How to estimate household peak power",
    "tip_load_house_body": "Add up the devices that may run at the same time:<br>· Air conditioner: 1HP ≈ 1000W, 1.5HP ≈ 1300W, 2HP ≈ 1800W (inverter units have a higher startup surge)<br>· Electric water heater ≈ 2000W (instant models ≈ 6000W — usually not suitable for off-grid backup)<br>· Fridge ≈ 150–250W, TV ≈ 100–200W, LED light ≈ 10–20W each, fan ≈ 50W<br>· Only count devices that run together; at night typically AC + fridge + lights, during the day add TV etc.<br>· The checklist above is prefilled with typical values — adjust quantity and power to the real site.",
    "tip_load_supermarket_title": "How to estimate supermarket / shop peak power",
    "tip_load_supermarket_body": "Freezers and lighting dominate, and they often run 24/7:<br>· Chest/upright freezer ≈ 300–500W each, display cabinet ≈ 200–400W each — add up all units<br>· Shelf/aisle lighting is typically 8–15W per meter; a common shelf light strip is about 80W. Total the whole-store lighting by tube count (e.g. 10 × 18W tubes ≈ 180W)<br>· Checkout (PC + printer + cash drawer) ≈ 100–200W<br>· Air conditioning counts during business hours, 1HP ≈ 1000W<br>· Freezers and lights that must stay on overnight should be marked as critical loads.",
    "tip_load_resort_title": "How to estimate resort / hotel peak power",
    "tip_load_resort_body": "Multiply by room count, then add shared equipment:<br>· Per room: AC 1HP ≈ 1000W (1.5HP ≈ 1300W) + lighting 100–200W + TV 100W + water heater 1500–2000W (storage type)<br>· Shared areas: corridor/lobby lighting by fixture count, water pump ≈ 750W, pool pump ≈ 1100W<br>· Do not assume every room is occupied and running at once — use 60%–80% occupancy and stagger pumps vs AC<br>· Guest rooms and the water pump that must survive an outage are critical loads; the pool pump can stay on the grid side.",
    "tip_load_cafe_title": "How to estimate café / restaurant peak power",
    "tip_load_cafe_body": "Cafés and restaurants have no desk lamps; the load is mostly heating and refrigeration:<br>· Coffee machine 1500–3000W (short, high surge — usually on the grid side so mains carries it)<br>· Ice maker ≈ 800W; fridge/freezer 200–400W each<br>· Induction cooker / electric oven 2000–4000W each; for delivery-heavy shops where they run almost all day, add up how many run together<br>· Lighting by pendant/spot count, typically 300–600W<br>· Commercial AC 1.5HP ≈ 1300W each, counted during business hours<br>· Only devices that cannot stop during an outage (e.g. an almost-always-on coffee machine or freezer) should be critical loads.",
    "tip_strategy_title": "About the three strategies",
    "tip_strategy_body": "Annual average daily peak sun hours: ~4.5h. Rainy season months average only ~3h, worst case single day ~2h. Dry season months average ~6h, best case up to 7h.<br><br><b>Option 1</b> — sized at 6h (dry-season average): enough in dry season, severely insufficient in rainy season, highest ROI.<br><b>Option 2</b> — sized at 4.5h (annual average): surplus in dry season, slightly insufficient in rainy season. Default and recommended.<br><b>Option 3</b> — sized at 3h (rainy-season average): large surplus in dry season, enough in rainy season, lowest ROI.",
