    "scenario_cafe": "Coffee shop / Restaurant",
    "scenario_house_guide": "Ask about each appliance one by one — air conditioner, water heater, fridge, TV, lighting: power, daytime hours, night hours. Use equivalent running hours for always-on devices such as the fridge.",
    "scenario_supermarket_guide": "Focus on freezers and display fridges: count them and ask whether they run 24h (these are critical loads that must stay on during outages). Lighting and AC follow business hours.",
    "scenario_resort_guide": "Ask room by room: AC, water heater, lighting, plus water pumps and pool pumps. Guest-room loads and water pumps are usually critical; pool pumps can stay on the grid side.",
    "scenario_cafe_guide": "Short high-power devices such as the coffee machine default to the grid side (do not tick critical) so utility power absorbs the surge. If delivery orders keep the machine running almost all day, tick critical and move it to the off-grid side, then choose a larger inverter.",
