    "tip_backup_title": "Backup critical load",
    "tip_backup_body": "In hybrid mode, loads are split into two groups:<br>· <b>Grid-side loads</b> — powered by the inverter together with utility power, so they are NOT limited by the inverter rating (the day/night loads above).<br>· <b>Backup critical loads</b> — powered from the backup (EPS) port during outages; the inverter bank must cover their peak power with 25% headroom, and multiple inverters can be paralleled to expand capacity.<br>Leave empty to size the inverter for all loads.",
