    "strategy_1": "高投资回报率，低发电量保障",
    "strategy_2": "中投资回报率，中发电量保障（默认推荐）",
    "strategy_3": "低投资回报率，高发电量保障",
    "got_it": "知道了",
    "tip_load_title": "如何估算峰值功率",
    "tip_load_body": "把同时使用的设备功率相加即可：<br>· 1匹空调峰值功率大约 1000W<br>· 2匹空调约 2000W<br>· 一台电脑（约200W）+ 一台小型冰箱（约200W）+ 几盏灯和一台风扇（约200W）+ 一台电视（约200W）",
    "tip_load_house_title": "如何估算家庭峰值功率",
    "tip_load_house_body": "把同一时段可能同时开启的设备功率相加：<br>· 空调 1 匹约 1000W、1.5 匹约 1300W、2 匹约 1800W（变频机启动峰值更高）<br>· 储水式电热水器约 2000W，即热式约 6000W（后者通常不建议接离网备用）<br>· 冰箱约 150–250W、电视约 100–200W、LED 灯每盏约 10–20W、风扇约 50W<br>· 只统计同一时段会同时运行的设备；夜间通常是空调 + 冰箱 + 照明，白天再加上电视等<br>· 上方清单已按典型值预填，按实际台数和功率修改即可。",
    "tip_load_supermarket_title": "如何估算超市 / 商铺峰值功率",
    "tip_load_supermarket_body": "重点是冷柜和照明，而且往往全天运行：<br>· 卧式 / 立式冷柜约 300–500W 每台，展示柜约 200–400W 每台，按数量叠加<br>· 货架过道照明通常每米约 8–15W，常见单条货架灯约 80W；整店照明按灯管数量合计（如 10 支 18W 灯管约 180W）<br>· 收银台（电脑 + 打印机 + 钱箱）约 100–200W<br>· 空调按营业时段计入，1 匹约 1000W<br>· 夜间必须继续运行的冷柜和照明应勾选为关键负载。",
    "tip_load_resort_title": "如何估算度假村 / 酒店峰值功率",
    "tip_load_resort_body": "按房间数量乘算，再叠加公共设备：<br>· 每间客房：空调 1 匹约 1000W（1.5 匹约 1300W）+ 照明 100–200W + 电视 100W + 储水式热水器 1500–2000W<br>· 公共区域：走廊 / 大堂照明按灯数合计，水泵约 750W，泳池泵约 1100W<br>· 不要把全部房间都按同时满负荷计算，通常按 60%–80% 入住率估算，并让水泵、泳池泵与空调错峰<br>· 停电时必须保障的客房和水泵设为关键负载，泳池泵可放在并网端。",
    "tip_load_cafe_title": "如何估算咖啡厅 / 饭店峰值功率",
    "tip_load_cafe_body": "咖啡厅和饭店一般没有台灯这类居家电器，负载主要来自加热与制冷设备：<br>· 咖啡机 1500–3000W（短时高功率，通常放并网端由市电承担冲击）<br>· 制冰机约 800W，冰箱 / 冷柜每台 200–400W<br>· 电磁炉、电烤箱每台 2000–4000W；外卖多、设备几乎常开的店，按实际同时开启的台数累加<br>· 照明按吊灯 / 射灯数量合计，一般 300–600W<br>· 商用空调 1.5 匹约 1300W 每台，按营业时段计入<br>· 只有停电也不能停的设备（如几乎全天运行的咖啡机、冷柜）才设为关键负载。",
    "tip_strategy_title": "三种配置策略说明",
    "tip_strategy_body": "参考日照：年平均单日日照时长约 4.5 小时；雨季月份平均只有约 3 小时，最差情况下单日最低日照约 2 小时；旱季月份平均可达约 6 小时，最好情况可达约 7 小时。<br><br><b>选项1</b>：按 6 小时（旱季平均水平）配置——旱季够用，雨季严重不足，投资回报率最高。<br><b>选项2</b>：按 4.5 小时（年平均）配置——旱季有冗余，雨季发电量略有不足。默认推荐。<br><b>选项3</b>：按 3 小时（雨季平均水平）配置——旱季发电量大量冗余，雨季发电量够用，投资回报率最低。",
