    "scenario_cafe": "咖啡厅 / 饭店",
    "scenario_house_guide": "逐项询问：空调、热水器、冰箱、电视、照明分别多大功率，白天开多久、夜间开多久。冰箱等常开设备按等效运行小时计算。",
    "scenario_supermarket_guide": "重点询问冷柜和展示柜的数量，以及是否 24 小时运行（这类是停电也不能断的关键负载）。照明和空调按营业时间填写。",
    "scenario_resort_guide": "按房间逐项询问：空调、热水器、照明，再加上水泵和泳池泵。客房负载和水泵通常设为关键负载，泳池泵可放并网端。",
    "scenario_cafe_guide": "咖啡机等短时高功率设备默认放并网端（不勾选关键负载），由市电承担冲击。若外卖多、咖啡机几乎全天运行，则勾选关键负载并放到离网端，同时选择更大功率的逆变器。",
