    "tip_backup_title": "什么是备用关键负载",
    "tip_backup_body": "混网模式下负载分为两组：<br>· <b>并网端负载</b>——由逆变器与市电共同带载，不受逆变器功率限制（即上方填写的白天/夜间负载）。<br>· <b>备用关键负载</b>——停电时由逆变器备用口（EPS）供电，逆变器组需按 1.25 倍余量覆盖其峰值功率；可通过多台逆变器并联扩容。<br>留空则按全部负载设计逆变器功率。",
    "invalid_backup_peak_power": "请输入有效的备用关键负载峰值功率",
