    "no_battery_fit": "没有可满足需求的在售电池：所需容量约 {need_kwh} kWh，超出单组最大并联数量（{max_qty} 块）。请减少夜间用电量或备用天数。",
    "no_panel_fit": "没有可满足需求的在售光伏板：所需阵列约 {need_kw} kW，超出最大数量限制（{max_qty} 块）。",
    "invalid_panel_qty": "光伏板数量必须是 1–200 之间的整数。",
    "panel_qty_string_mismatch": "每串光伏板数量必须相同，请选择可均分为整串的数量。",
    "panel_string_limit_exceeded": "所选 {qty} 块不满足组串规则：每串最多 {max_series} 块（单块开路电压 {module_voc}V，MPPT 电压上限 {mppt_voltage}V），最多 {max_strings} 串并联（单块短路电流 {module_isc}A，每路 MPPT 电流上限 {mppt_current}A × {mppt_channels} 路）。请选择不超过 {max_qty} 块且每串数量相同的配置。",
    "no_panel_string_fit": "按组串规则，在售逆变器无法接入满足需求（约 {need_kw} kW）的光伏阵列：每串块数需一致，且组串电压和并联电流不能超过 MPPT 上限。请联系销售人员。",
