    "strategy": "Estrategia de configuración",
    "strategy_1": "ROI alto, generación garantizada baja",
    "strategy_2": "ROI medio, generación media (recomendada)",
    "strategy_3": "ROI bajo, generación garantizada alta",
    "got_it": "Entendido",
    "tip_load_title": "Cómo estimar la potencia pico",
    "tip_load_body": "Suma la potencia de todos los equipos que funcionan a la vez:<br>· Aire acondicionado de 1HP: ~1000W pico<br>· Aire acondicionado de 2HP: ~2000W pico<br>· Una computadora (~200W) + un refrigerador pequeño (~200W) + unas luces y un ventilador (~200W) + un televisor (~200W)",
    "tip_load_house_title": "Cómo estimar la potencia pico del hogar",
    "tip_load_house_body": "Suma los equipos que pueden funcionar a la vez:<br>· Aire acondicionado: 1HP ≈ 1000W, 1.5HP ≈ 1300W, 2HP ≈ 1800W (los equipos inverter tienen mayor pico de arranque)<br>· Calentador de agua eléctrico ≈ 2000W (los de paso ≈ 6000W — normalmente no aptos para respaldo aislado)<br>· Refrigerador ≈ 150–250W, TV ≈ 100–200W, luz LED ≈ 10–20W cada una, ventilador ≈ 50W<br>· Cuenta solo los equipos que funcionan juntos; de noche suelen ser A/A + refrigerador + luces, y de día añade TV, etc.<br>· La lista anterior viene precargada con valores típicos: ajusta cantidades y potencias al sitio real.",
    "tip_load_supermarket_title": "Cómo estimar la potencia pico de supermercado / tienda",
    "tip_load_supermarket_body": "Los congeladores y la iluminación dominan, y suelen funcionar 24/7:<br>· Congelador horizontal/vertical ≈ 300–500W cada uno, vitrina ≈ 200–400W cada una — suma todas las unidades<br>· La iluminación de estantes/pasillos suele ser de 8–15W por metro; una tira de luz típica de estante ronda los 80W. Calcula la iluminación total de la tienda por número de tubos (p. ej. 10 tubos de 18W ≈ 180W)<br>· Caja (PC + impresora + cajón de dinero) ≈ 100–200W<br>· El aire acondicionado cuenta en horario comercial, 1HP ≈ 1000W<br>· Los congeladores y las luces que deben seguir encendidos durante la noche se marcan como cargas críticas.",
    "tip_load_resort_title": "Cómo estimar la potencia pico de resort / hotel",
    "tip_load_resort_body": "Multiplica por el número de habitaciones y añade los equipos comunes:<br>· Por habitación: A/A 1HP ≈ 1000W (1.5HP ≈ 1300W) + iluminación 100–200W + TV 100W + calentador de agua 1500–2000W (tipo con tanque)<br>· Áreas comunes: iluminación de pasillos/recibidor por número de luminarias, bomba de agua ≈ 750W, bomba de alberca ≈ 1100W<br>· No asumas que todas las habitaciones están ocupadas y en uso a la vez — usa 60%–80% de ocupación y desfasa bombas y A/A<br>· Las habitaciones y la bomba de agua que debe seguir funcionando en cortes son cargas críticas; la bomba de alberca puede quedar del lado de la red.",
    "tip_load_cafe_title": "Cómo estimar la potencia pico de cafetería / restaurante",
    "tip_load_cafe_body": "Cafeterías y restaurantes no tienen lámparas de escritorio; la carga es sobre todo calefacción y refrigeración:<br>· Cafetera 1500–3000W (picos cortos y altos — normalmente del lado de la red para que la red la soporte)<br>· Máquina de hielo ≈ 800W; refrigerador/congelador 200–400W cada uno<br>· Cocina de inducción / horno eléctrico 2000–4000W cada uno; en locales con muchos pedidos a domicilio que los usan casi todo el día, cuenta cuántos funcionan a la vez<br>· Iluminación por número de colgantes/focos, normalmente 300–600W<br>· A/A comercial 1.5HP ≈ 1300W cada uno, contado en horario comercial<br>· Solo los equipos que no pueden detenerse en un corte (p. ej. una cafetera o un congelador casi siempre en uso) deben ser cargas críticas.",
    "tip_strategy_title": "Sobre las tres estrategias",
    "tip_strategy_body": "Promedio diario anual de horas pico de sol: ~4.5h. Los meses de lluvias promedian solo ~3h, con un peor caso de ~2h en un solo día. Los meses de sequía promedian ~6h, con máximos de hasta 7h.<br><br><b>Opción 1</b> — dimensionado a 6h (promedio de sequía): suficiente en sequía, muy insuficiente en lluvias, el ROI más alto.<br><b>Opción 2</b> — dimensionado a 4.5h (promedio anual): superávit en sequía, levemente insuficiente en lluvias. Opción predeterminada y recomendada.<br><b>Opción 3</b> — dimensionado a 3h (promedio de lluvias): gran superávit en sequía, suficiente en lluvias, el ROI más bajo.",
    "my_cases": "Mis casos",
