    "system_mode_note": "El modo aislado siempre necesita al menos una batería cuya salida cubra 1.2× el pico diurno. El híbrido conectado a red puede funcionar sin batería si no hay carga nocturna.",
    "system_mode_required": "Elige primero modo aislado puro o híbrido",
