    "usage_scenario": "¿Dónde se usa el sistema solar?",
    "scenario_none": "Elegir después",
    "scenario_house": "Vivienda",
    "scenario_supermarket": "Supermercado / Tienda",
    "scenario_resort": "Resort / Hotel",
    "scenario_cafe": "Cafetería / Restaurante",
    "scenario_house_guide": "Pregunta aparato por aparato — aire acondicionado, calentador de agua, refrigerador, TV, iluminación: potencia, horas diurnas, horas nocturnas. Usa horas equivalentes de funcionamiento para equipos siempre encendidos, como el refrigerador.",
    "scenario_supermarket_guide": "Céntrate en los congeladores y las vitrinas refrigeradas: cuéntalos y pregunta si funcionan 24h (son cargas críticas que deben seguir encendidas en cortes). La iluminación y el A/A siguen el horario comercial.",
    "scenario_resort_guide": "Pregunta habitación por habitación: A/A, calentador de agua, iluminación, además de bombas de agua y de alberca. Las cargas de habitaciones y las bombas de agua suelen ser críticas; las bombas de alberca pueden quedar del lado de la red.",
    "scenario_cafe_guide": "Los equipos de uso corto y alta potencia, como la cafetera, van por defecto al lado de la red (no marques crítica) para que la red absorba el pico. Si los pedidos a domicilio la mantienen en uso casi todo el día, márcala como crítica, pásala al lado aislado y elige un inversor más grande.",
