    "install_fee_survey_note": "El costo exacto de instalación se confirmará después de una inspección en sitio.",
    "invalid_day_peak_power": "Ingresa una potencia pico diurna válida",
    "invalid_day_hours": "Las horas diurnas deben ser 0-8 (8:00-16:00)",
    "invalid_night_peak_power": "Ingresa una potencia pico nocturna válida",
    "invalid_night_hours": "Las horas nocturnas deben ser 0-16 (16:00-8:00)",
    "selected_inverter_mode_mismatch": "El modo del inversor seleccionado no coincide con el caso",
    "backup_peak_power": "Pico de carga crítica de respaldo (W)",
    "tip_backup_title": "Carga crítica de respaldo",
    "tip_backup_body": "En modo híbrido las cargas se dividen en dos grupos:<br>· <b>Cargas del lado de la red</b> — las alimenta el inversor junto con la red, por lo que NO están limitadas por la capacidad del inversor (las cargas diurnas/nocturnas de arriba).<br>· <b>Cargas críticas de respaldo</b> — se alimentan desde el puerto de respaldo (EPS) durante cortes; el banco de inversores debe cubrir su potencia pico con 25% de margen, y se pueden poner varios inversores en paralelo para ampliar la capacidad.<br>Deja vacío para dimensionar el inversor para todas las cargas.",
    "invalid_backup_peak_power": "Ingresa una potencia pico de carga crítica de respaldo válida",
    "no_inverter_fit": "Ningún inversor en venta cubre la potencia requerida: se necesitan {need_kw} kW (incl. 25% de margen) aun con el máximo de unidades en paralelo. Reduce la carga o contacta a ventas.",
    "no_battery_fit": "Ninguna batería en venta cubre la capacidad requerida (~{need_kwh} kWh) dentro del máximo de {max_qty} unidades en paralelo. Reduce el consumo nocturno o los días de respaldo.",
    "no_panel_fit": "Ningún panel solar en venta cubre el arreglo requerido (~{need_kw} kW) dentro del máximo de {max_qty} piezas.",
    "invalid_panel_qty": "La cantidad de paneles debe ser un número entero entre 1 y 200.",
    "panel_qty_string_mismatch": "Todos los strings deben tener el mismo número de paneles. Elige una cantidad que se divida en strings iguales.",
    "panel_string_limit_exceeded": "{qty} paneles superan los límites de strings: máximo {max_series} paneles por string (Voc del módulo {module_voc}V, máx. MPPT {mppt_voltage}V), máximo {max_strings} strings en paralelo (Isc del módulo {module_isc}A, máx. MPPT {mppt_current}A × {mppt_channels} entradas). Elige no más de {max_qty} paneles con strings de igual longitud.",
    "no_panel_string_fit": "Ningún inversor en venta admite el arreglo requerido (~{need_kw} kW) bajo las reglas de strings: igual número de paneles por string, Voc del string dentro del límite de voltaje del MPPT y corriente en paralelo dentro del límite de corriente del MPPT. Contacta a ventas.",
    "no_voltage_match": "Ninguna batería en venta coincide con el voltaje de batería de algún inversor adecuado.",
    "battery_less_inverter_out_of_stock": "No hay inversores híbridos con arranque sin batería en existencia. Confirma con el equipo de ventas cuándo puede llegar un pedido.",
    "no_battery_less_inverter": "Ningún inversor híbrido del catálogo admite arranque sin batería, por lo que se requiere batería.",
    "selected_inverter_no_battery_start": "El inversor seleccionado no puede arrancar sin batería. Elige otro modelo o agrega una batería.",
    "grid_parallel_max": "Unidades en paralelo del lado de red (solo híbrido)",
    "offgrid_parallel_max": "Unidades en paralelo aislado (capacidad de paralelo)",
    "grid_parallel_short": "Paralelo de red",
    "offgrid_parallel_short": "Paralelo aislado",
    "grid_output_max_w": "Salida máx. conectado a red (W)",
    "grid_output_hint": "Solo híbrido. Carga máxima que un inversor soporta en modo conectado a red; deja vacío para paso ilimitado.",
    "battery_less_start": "Arranque sin batería",
    "battery_less_hint": "Solo híbrido. Activado significa que el inversor puede arrancar y alimentar cargas sin batería.",
    "parallel_hint": "1 = ninguno. El paralelo del lado de red aplica solo a inversores híbridos; el paralelo de salida aislado aplica tanto a inversores híbridos como aislados.",
    "hybrid_load_note": "Modo híbrido: las cargas diurnas/nocturnas de arriba son cargas del lado de red, alimentadas por el inversor junto con la red — no limitadas por la capacidad del inversor.",
    "backup_load_note": "Potencia pico de los equipos críticos alimentados desde el puerto de respaldo (EPS) durante cortes. El banco de inversores se dimensiona con este valor (25% de margen) y puede ampliarse poniendo varias unidades en paralelo. Deja vacío para dimensionar para todas las cargas.",
    "note_hybrid_backup": "Modo híbrido: el inversor se dimensiona por la carga crítica de respaldo (incl. 25% de margen); las cargas del lado de red se alimentan junto con la red y no están limitadas por la capacidad del inversor.",
    "note_hybrid_no_battery": "Modo híbrido conectado a red: no se requiere batería cuando no hay carga nocturna.",
    "ai_assistant": "Asistente de IA",
