    "got_it": "Verstanden",
    "tip_load_title": "So schätzen Sie die Spitzenleistung ab",
    "tip_load_body": "Addieren Sie die Leistung aller gleichzeitig laufenden Geräte:<br>· Klimaanlage 1 PS: ca. 1000 W Spitzenleistung<br>· Klimaanlage 2 PS: ca. 2000 W Spitzenleistung<br>· Ein Computer (~200 W) + ein kleiner Kühlschrank (~200 W) + einige Lampen und ein Ventilator (~200 W) + ein Fernseher (~200 W)",
    "tip_load_house_title": "So schätzen Sie die Haushalts-Spitzenleistung ab",
    "tip_load_house_body": "Addieren Sie alle Geräte, die gleichzeitig laufen können:<br>· Klimaanlage: 1 PS ≈ 1000 W, 1,5 PS ≈ 1300 W, 2 PS ≈ 1800 W (Inverter-Geräte haben eine höhere Anlaufspitze)<br>· Elektrischer Warmwasserbereiter ≈ 2000 W (Durchlauferhitzer ≈ 6000 W – meist nicht für Inselbetrieb-Backup geeignet)<br>· Kühlschrank ≈ 150–250 W, Fernseher ≈ 100–200 W, LED-Lampe ≈ 10–20 W je Stück, Ventilator ≈ 50 W<br>· Nur Geräte zählen, die zusammen laufen; nachts typischerweise Klimaanlage + Kühlschrank + Beleuchtung, tagsüber zusätzlich Fernseher usw.<br>· Die obige Checkliste ist mit typischen Werten vorbelegt – passen Sie Anzahl und Leistung an den realen Standort an.",
    "tip_load_supermarket_title": "So schätzen Sie die Spitzenleistung von Supermarkt / Laden ab",
    "tip_load_supermarket_body": "Gefriergeräte und Beleuchtung dominieren und laufen oft 24/7:<br>· Gefriertruhe/-schrank ≈ 300–500 W je Stück, Kühlvitrine ≈ 200–400 W je Stück – alle Geräte zusammenzählen<br>· Regal-/Gangbeleuchtung typisch 8–15 W pro Meter; ein übliches Regal-Lichtband hat ca. 80 W. Die gesamte Ladenbeleuchtung über die Röhrenanzahl summieren (z. B. 10 Röhren × 18 W ≈ 180 W)<br>· Kasse (PC + Drucker + Kassenlade) ≈ 100–200 W<br>· Klimatisierung zählt während der Öffnungszeiten, 1 PS ≈ 1000 W<br>· Gefriergeräte und Leuchten, die über Nacht laufen müssen, als kritische Lasten markieren.",
    "tip_load_resort_title": "So schätzen Sie die Spitzenleistung von Resort / Hotel ab",
    "tip_load_resort_body": "Mit der Zimmeranzahl multiplizieren, dann gemeinschaftlich genutzte Geräte ergänzen:<br>· Pro Zimmer: Klimaanlage 1 PS ≈ 1000 W (1,5 PS ≈ 1300 W) + Beleuchtung 100–200 W + Fernseher 100 W + Warmwasserbereiter 1500–2000 W (Speichertyp)<br>· Gemeinschaftsbereiche: Flur-/Lobbybeleuchtung nach Leuchtenanzahl, Wasserpumpe ≈ 750 W, Poolpumpe ≈ 1100 W<br>· Nicht davon ausgehen, dass jedes Zimmer belegt und alles gleichzeitig läuft – 60–80 % Belegung ansetzen und Pumpen sowie Klimaanlage zeitversetzt betreiben<br>· Gästezimmer und die Wasserpumpe, die einen Netzausfall überstehen muss, sind kritische Lasten; die Poolpumpe kann auf der Netzseite bleiben.",
    "tip_load_cafe_title": "So schätzen Sie die Spitzenleistung von Café / Restaurant ab",
    "tip_load_cafe_body": "Cafés und Restaurants haben keine Schreibtischlampen; die Last besteht meist aus Wärme- und Kühlgeräten:<br>· Kaffeemaschine 1500–3000 W (kurz, hohe Anlaufspitze – meist auf der Netzseite, damit das Netz sie trägt)<br>· Eiswürfelbereiter ≈ 800 W; Kühlschrank/Gefrierschrank je 200–400 W<br>· Induktionskochfeld / Elektrobackofen je 2000–4000 W; bei starkem Liefergeschäft, wo sie fast den ganzen Tag laufen, zusammenzählen, wie viele gleichzeitig laufen<br>· Beleuchtung nach Anzahl der Pendel-/Spotleuchten, typisch 300–600 W<br>· Gewerbeklimaanlage 1,5 PS ≈ 1300 W je Gerät, gezählt während der Öffnungszeiten<br>· Nur Geräte, die bei einem Ausfall nicht stoppen dürfen (z. B. eine fast durchgehend laufende Kaffeemaschine oder ein Gefrierschrank), sollten kritische Lasten sein.",
    "tip_strategy_title": "Über die drei Strategien",
    "tip_strategy_body": "Jährlicher Tagesdurchschnitt der Spitzen-Sonnenstunden: ~4,5 h. Regenmonate kommen im Schnitt nur auf ~3 h, der schlimmste Einzeltag auf ~2 h. Trockenmonate liegen im Schnitt bei ~6 h, im besten Fall bis zu 7 h.<br><br><b>Variante 1</b> – ausgelegt auf 6 h (Trockenzeit-Durchschnitt): in der Trockenzeit ausreichend, in der Regenzeit deutlich zu wenig, höchster ROI.<br><b>Variante 2</b> – ausgelegt auf 4,5 h (Jahresdurchschnitt): Überschuss in der Trockenzeit, in der Regenzeit leicht zu wenig. Standard und empfohlen.<br><b>Variante 3</b> – ausgelegt auf 3 h (Regenzeit-Durchschnitt): großer Überschuss in der Trockenzeit, in der Regenzeit ausreichend, niedrigster ROI.",
