    "scenario_resort": "Resort / Hotel",
    "scenario_cafe": "Café / Restaurant",
    "scenario_house_guide": "Fragen Sie jedes Gerät einzeln ab – Klimaanlage, Warmwasserbereiter, Kühlschrank, Fernseher, Beleuchtung: Leistung, Stunden am Tag, Stunden in der Nacht. Für Dauerverbraucher wie den Kühlschrank äquivalente Laufstunden verwenden.",
    "scenario_supermarket_guide": "Konzentrieren Sie sich auf Gefriergeräte und Kühlvitrinen: Zählen Sie sie und fragen Sie, ob sie 24 h laufen (kritische Lasten, die bei Netzausfällen weiterlaufen müssen). Beleuchtung und Klimatisierung folgen den Öffnungszeiten.",
    "scenario_resort_guide": "Fragen Sie Zimmer für Zimmer ab: Klimaanlage, Warmwasserbereiter, Beleuchtung, dazu Wasserpumpen und Poolpumpen. Lasten in Gästezimmern und Wasserpumpen sind meist kritisch; Poolpumpen können auf der Netzseite bleiben.",
    "scenario_cafe_guide": "Kurz laufende Hochleistungsgeräte wie die Kaffeemaschine gehören standardmäßig auf die Netzseite (nicht als kritisch markieren), damit das Netz die Anlaufspitze aufnimmt. Wenn Lieferservices die Maschine fast den ganzen Tag laufen lassen, markieren Sie sie als kritisch, verschieben Sie sie auf die Inselseite und wählen Sie einen größeren Wechselrichter.",
