    "backup_peak_power": "Spitzenleistung kritische Backup-Last (W)",
    "tip_backup_title": "Kritische Backup-Last",
    "tip_backup_body": "Im Hybrid-Modus werden Lasten in zwei Gruppen geteilt:<br>· <b>Netzseitige Lasten</b> – vom Wechselrichter zusammen mit dem Netz versorgt, daher NICHT durch die Nennleistung des Wechselrichters begrenzt (die Tag/Nacht-Lasten oben).<br>· <b>Kritische Backup-Lasten</b> – bei Ausfällen über den Backup-Anschluss (EPS) versorgt; die Wechselrichter-Bank muss ihre Spitzenleistung mit 25 % Reserve abdecken, und mehrere Wechselrichter können zur Kapazitätserweiterung parallel geschaltet werden.<br>Leer lassen, um den Wechselrichter für alle Lasten auszulegen.",
    "invalid_backup_peak_power": "Bitte eine gültige Spitzenleistung der kritischen Backup-Last eingeben",
    "no_inverter_fit": "Kein Wechselrichter im Verkauf kann die erforderliche Leistung abdecken: {need_kw} kW benötigt (inkl. 25 % Reserve), selbst bei maximaler Parallelschaltung. Bitte reduzieren Sie die Last oder kontaktieren Sie den Vertrieb.",
    "no_battery_fit": "Keine Batterie im Verkauf kann die erforderliche Kapazität (~{need_kwh} kWh) mit maximal {max_qty} Paralleleinheiten abdecken. Bitte reduzieren Sie den Nachtverbrauch oder die Autonomie-Tage.",
    "no_panel_fit": "Kein Solarmodul im Verkauf kann das erforderliche Feld (~{need_kw} kW) mit maximal {max_qty} Modulen abdecken.",
    "invalid_panel_qty": "Die Modulanzahl muss eine ganze Zahl zwischen 1 und 200 sein.",
    "panel_qty_string_mismatch": "Alle Strings müssen gleich viele Module enthalten. Wählen Sie eine Anzahl, die sich in gleich große Strings aufteilt.",
    "panel_string_limit_exceeded": "{qty} Module überschreiten die String-Grenzen: max. {max_series} Module pro String (Modul-Voc {module_voc} V, MPPT max. {mppt_voltage} V), max. {max_strings} parallele Strings (Modul-Isc {module_isc} A, MPPT max. {mppt_current} A × {mppt_channels} Eingänge). Wählen Sie höchstens {max_qty} Module mit gleicher String-Länge.",
    "no_panel_string_fit": "Kein Wechselrichter im Verkauf kann das erforderliche Feld (~{need_kw} kW) unter den String-Regeln aufnehmen: gleiche Modulanzahl pro String, String-Voc innerhalb der MPPT-Spannungsgrenze und Parallelstrom innerhalb der MPPT-Stromgrenze. Bitte kontaktieren Sie den Vertrieb.",
    "no_voltage_match": "Keine Batterie im Verkauf passt zur Batteriespannung eines der geeigneten Wechselrichter.",
    "battery_less_inverter_out_of_stock": "Zurzeit ist kein Hybrid-Wechselrichter mit Start ohne Batterie auf Lager. Bitte klären Sie mit dem Vertriebsteam, wann eine Bestellung eintreffen kann.",
    "no_battery_less_inverter": "Kein Hybrid-Wechselrichter im Katalog unterstützt den Start ohne Batterie, daher ist eine Batterie erforderlich.",
    "selected_inverter_no_battery_start": "Der gewählte Wechselrichter kann nicht ohne Batterie starten. Wählen Sie ein anderes Modell oder fügen Sie eine Batterie hinzu.",
    "grid_parallel_max": "Parallele Einheiten netzseitig (nur Hybrid)",
    "offgrid_parallel_max": "Parallele Einheiten Inselbetrieb (Parallelfähigkeit)",
    "grid_parallel_short": "Netz-Parallel",
    "offgrid_parallel_short": "Insel-Parallel",
    "grid_output_max_w": "Max. Ausgangsleistung netzgekoppelt (W)",
    "grid_output_hint": "Nur Hybrid. Maximale Last, die ein Wechselrichter im netzgekoppelten Modus tragen kann; leer lassen für unbegrenzte Durchleitung.",
    "battery_less_start": "Start ohne Batterie",
    "battery_less_hint": "Nur Hybrid. Aktiviert bedeutet, dass der Wechselrichter ohne Batterie starten und Lasten tragen kann.",
    "parallel_hint": "1 = keine Parallelschaltung. Netzseitiger Parallelbetrieb gilt nur für Hybrid-Wechselrichter; der Ausgangs-Parallelbetrieb im Inselbetrieb gilt für Hybrid- und Insel-Wechselrichter.",
    "hybrid_load_note": "Hybrid-Modus: Die Tag/Nacht-Lasten oben sind netzseitige Lasten, die der Wechselrichter zusammen mit dem Netz trägt – nicht begrenzt durch die Nennleistung des Wechselrichters.",
    "backup_load_note": "Spitzenleistung der kritischen Geräte, die bei Ausfällen über den Backup-Anschluss (EPS) versorgt werden. Die Wechselrichter-Bank wird nach diesem Wert ausgelegt (25 % Reserve) und lässt sich durch Parallelschaltung mehrerer Geräte erweitern. Leer lassen, um für alle Lasten auszulegen.",
    "note_hybrid_backup": "Hybrid-Modus: Der Wechselrichter wird nach der kritischen Backup-Last ausgelegt (inkl. 25 % Reserve); netzseitige Lasten werden zusammen mit dem Netz getragen und sind nicht durch die Nennleistung des Wechselrichters begrenzt.",
    "note_hybrid_no_battery": "Hybrid netzgekoppelt: Keine Batterie erforderlich, wenn es keine Nachtladung gibt.",
