    "ai_welcome": "Hallo! Fragen Sie mich alles zur App-Nutzung oder Solaranlagen-Konfiguration. Ihre Frage wird mit unseren Wissensdatenbanken kombiniert und kopiert – danach öffnet sich eine kostenlose KI-Seite, einfach einfügen und senden.",
