    "strategy_3": "ROI faible, production garantie élevée",
    "got_it": "Compris",
    "tip_load_title": "Comment estimer la puissance de pointe",
    "tip_load_body": "Additionnez la puissance de tous les appareils fonctionnant en même temps :<br>· Climatiseur 1HP : ~1000W de pointe<br>· Climatiseur 2HP : ~2000W de pointe<br>· Un ordinateur (~200W) + un petit réfrigérateur (~200W) + quelques lampes et un ventilateur (~200W) + une télévision (~200W)",
    "tip_load_house_title": "Comment estimer la puissance de pointe d'un logement",
    "tip_load_house_body": "Additionnez les appareils pouvant fonctionner en même temps :<br>· Climatiseur : 1HP ≈ 1000W, 1.5HP ≈ 1300W, 2HP ≈ 1800W (les modèles inverter ont un pic de démarrage plus élevé)<br>· Chauffe-eau électrique ≈ 2000W (les modèles instantanés ≈ 6000W — généralement inadaptés au secours hors réseau)<br>· Réfrigérateur ≈ 150–250W, télévision ≈ 100–200W, lampe LED ≈ 10–20W chacune, ventilateur ≈ 50W<br>· Ne comptez que les appareils qui tournent ensemble ; la nuit : généralement clim + réfrigérateur + lampes, le jour ajoutez la télévision etc.<br>· La liste ci-dessus est préremplie avec des valeurs types — ajustez quantités et puissances au site réel.",
    "tip_load_supermarket_title": "Comment estimer la puissance de pointe d'un supermarché / commerce",
    "tip_load_supermarket_body": "Les congélateurs et l'éclairage dominent, et ils tournent souvent 24h/24 et 7j/7 :<br>· Congélateur armoire/vertical ≈ 300–500W chacun, vitrine réfrigérée ≈ 200–400W chacun — additionnez toutes les unités<br>· L'éclairage des rayons/allées est typiquement de 8–15W par mètre ; un ruban lumineux de rayon fait environ 80W. Totalisez l'éclairage du magasin par nombre de tubes (ex. 10 × 18W ≈ 180W)<br>· Caisse (PC + imprimante + tiroir-caisse) ≈ 100–200W<br>· La climatisation compte pendant les heures d'ouverture, 1HP ≈ 1000W<br>· Les congélateurs et lampes qui doivent rester allumés la nuit doivent être marqués comme charges critiques.",
    "tip_load_resort_title": "Comment estimer la puissance de pointe d'un complexe touristique / hôtel",
    "tip_load_resort_body": "Multipliez par le nombre de chambres, puis ajoutez les équipements communs :<br>· Par chambre : clim 1HP ≈ 1000W (1.5HP ≈ 1300W) + éclairage 100–200W + télévision 100W + chauffe-eau 1500–2000W (type à accumulation)<br>· Espaces communs : éclairage couloir/réception selon le nombre de luminaires, pompe à eau ≈ 750W, pompe de piscine ≈ 1100W<br>· Ne supposez pas que toutes les chambres soient occupées et en marche en même temps — utilisez un taux d'occupation de 60 % à 80 % et décalez les pompes par rapport à la clim<br>· Les chambres d'hôtes et la pompe à eau qui doivent survivre à une coupure sont des charges critiques ; la pompe de piscine peut rester côté réseau.",
    "tip_load_cafe_title": "Comment estimer la puissance de pointe d'un café / restaurant",
    "tip_load_cafe_body": "Cafés et restaurants n'ont pas de lampes de bureau ; la charge est surtout du chauffage et du froid :<br>· Machine à café 1500–3000W (brève, fort pic — généralement côté réseau pour que le secteur l'absorbe)<br>· Machine à glaçons ≈ 800W ; réfrigérateur/congélateur 200–400W chacun<br>· Plaque à induction / four électrique 2000–4000W chacun ; pour les commerces très livrés où ils tournent presque toute la journée, additionnez ceux qui tournent ensemble<br>· Éclairage selon le nombre de suspensions/spots, typiquement 300–600W<br>· Clim commercial 1.5HP ≈ 1300W chacun, compté pendant les heures d'ouverture<br>· Seuls les appareils qui ne peuvent pas s'arrêter pendant une coupure (ex. machine à café presque toujours en marche ou congélateur) doivent être des charges critiques.",
    "tip_strategy_title": "À propos des trois stratégies",
    "tip_strategy_body": "Moyenne annuelle des heures d'ensoleillement de pointe : ~4,5h. Les mois de la saison des pluies tournent autour de ~3h, pire cas une journée ~2h. Les mois de la saison sèche font en moyenne ~6h, au mieux jusqu'à 7h.<br><br><b>Option 1</b> — dimensionnée à 6h (moyenne saison sèche) : suffisante en saison sèche, très insuffisante en saison des pluies, ROI le plus élevé.<br><b>Option 2</b> — dimensionnée à 4,5h (moyenne annuelle) : excédent en saison sèche, légèrement insuffisant en saison des pluies. Par défaut et recommandé.<br><b>Option 3</b> — dimensionnée à 3h (moyenne saison des pluies) : fort excédent en saison sèche, suffisant en saison des pluies, ROI le plus faible.",
    "my_cases": "Mes projets",
    "add_case": "+ Ajouter un projet",
    "edit_case": "Modifier le projet",
