    "system_mode_note": "Le hors réseau exige toujours au moins une batterie dont la sortie couvre 1,2× la pointe de jour. L'hybride raccordé au réseau peut fonctionner sans batterie en l'absence de charge nocturne.",
    "system_mode_required": "Choisissez d'abord le mode hors réseau pur ou hybride",
