    "usage_scenario": "Où le système solaire est-il utilisé ?",
    "scenario_none": "Choisir plus tard",
    "scenario_house": "Logement",
    "scenario_supermarket": "Supermarché / commerce",
    "scenario_resort": "Complexe touristique / hôtel",
    "scenario_cafe": "Café / restaurant",
    "scenario_house_guide": "Interrogez chaque appareil un par un — climatiseur, chauffe-eau, réfrigérateur, télévision, éclairage : puissance, heures de jour, heures de nuit. Utilisez des heures de fonctionnement équivalentes pour les appareils toujours en marche comme le réfrigérateur.",
    "scenario_supermarket_guide": "Concentrez-vous sur les congélateurs et vitrines réfrigérées : comptez-les et demandez s'ils tournent 24h (ce sont des charges critiques qui doivent rester alimentées pendant les coupures). L'éclairage et la clim suivent les heures d'ouverture.",
    "scenario_resort_guide": "Interrogez chambre par chambre : clim, chauffe-eau, éclairage, plus les pompes à eau et pompes de piscine. Les charges des chambres et les pompes à eau sont généralement critiques ; les pompes de piscine peuvent rester côté réseau.",
    "scenario_cafe_guide": "Les appareils courts et puissants comme la machine à café vont par défaut côté réseau (ne cochez pas critique) afin que le secteur absorbe le pic. Si les commandes en livraison la font tourner presque toute la journée, cochez critique et passez-la côté hors réseau, puis choisissez un onduleur plus puissant.",
