    "invalid_night_peak_power": "Veuillez saisir une puissance de pointe de nuit valide",
    "invalid_night_hours": "Les heures d'utilisation de nuit doivent être entre 0 et 16 (16h00-8h00)",
    "selected_inverter_mode_mismatch": "Le mode de l'onduleur sélectionné ne correspond pas au projet",
    "backup_peak_power": "Pointe de la charge critique de secours (W)",
    "tip_backup_title": "Charge critique de secours",
    "tip_backup_body": "En mode hybride, les charges sont réparties en deux groupes :<br>· <b>Charges côté réseau</b> — alimentées par l'onduleur avec le secteur, donc NON limitées par la puissance de l'onduleur (les charges jour/nuit ci-dessus).<br>· <b>Charges critiques de secours</b> — alimentées depuis le port de secours (EPS) pendant les coupures ; le parc d'onduleurs doit couvrir leur puissance de pointe avec 25 % de marge, et plusieurs onduleurs peuvent être mis en parallèle pour étendre la capacité.<br>Laissez vide pour dimensionner l'onduleur pour toutes les charges.",
    "invalid_backup_peak_power": "Veuillez saisir une pointe de charge critique de secours valide",
    "no_inverter_fit": "Aucun onduleur en vente ne peut couvrir la puissance requise : {need_kw} kW nécessaires (marge de 25 % incluse), même au maximum d'unités en parallèle. Réduisez la charge ou contactez le service commercial.",
    "no_battery_fit": "Aucune batterie en vente ne peut couvrir la capacité requise (~{need_kwh} kWh) dans la limite de {max_qty} unités en parallèle. Réduisez la consommation nocturne ou les jours d'autonomie.",
    "no_panel_fit": "Aucun panneau solaire en vente ne peut couvrir le champ requis (~{need_kw} kW) dans la limite de {max_qty} panneaux.",
    "invalid_panel_qty": "Le nombre de panneaux doit être un nombre entier entre 1 et 200.",
    "panel_qty_string_mismatch": "Tous les strings doivent contenir le même nombre de panneaux. Choisissez un nombre qui se répartit en strings égaux.",
    "panel_string_limit_exceeded": "{qty} panneaux dépassent les limites de string : max {max_series} panneaux par string (Voc du module {module_voc}V, max MPPT {mppt_voltage}V), max {max_strings} strings en parallèle (Isc du module {module_isc}A, max MPPT {mppt_current}A × {mppt_channels} entrées). Choisissez au plus {max_qty} panneaux avec des strings de longueur égale.",
    "no_panel_string_fit": "Aucun onduleur en vente ne peut accueillir le champ requis (~{need_kw} kW) selon les règles de string : même nombre de panneaux par string, Voc du string dans la limite de tension MPPT et courant parallèle dans la limite de courant MPPT. Veuillez contacter le service commercial.",
    "no_voltage_match": "Aucune batterie en vente ne correspond à la tension de batterie d'un onduleur convenable.",
    "battery_less_inverter_out_of_stock": "Aucun onduleur hybride à démarrage sans batterie n'est actuellement en stock. Veuillez confirmer avec l'équipe commerciale la date d'arrivée d'une commande.",
    "no_battery_less_inverter": "Aucun onduleur hybride du catalogue ne prend en charge le démarrage sans batterie : une batterie est donc requise.",
    "selected_inverter_no_battery_start": "L'onduleur sélectionné ne peut pas démarrer sans batterie. Choisissez un autre modèle ou ajoutez une batterie.",
