    "tip_load_title": "ピーク電力の見積もり方",
    "tip_load_body": "同時に稼働するすべての機器の電力を合計します：<br>・エアコン1HP：ピーク約1000W<br>・エアコン2HP：ピーク約2000W<br>・パソコン1台（約200W）＋小型冷蔵庫1台（約200W）＋照明と扇風機数台（約200W）＋テレビ1台（約200W）",
    "tip_load_house_title": "家庭のピーク電力の見積もり方",
    "tip_load_house_body": "同時に稼働する可能性のある機器を合計します：<br>・エアコン：1HP ≈ 1000W、1.5HP ≈ 1300W、2HP ≈ 1800W（インバーター機は起動時の突入電流が大きめ）<br>・電気温水器 ≈ 2000W（瞬間式は ≈ 6000W。通常はオフグリッドのバックアップには不向き）<br>・冷蔵庫 ≈ 150〜250W、テレビ ≈ 100〜200W、LED照明 ≈ 各10〜20W、扇風機 ≈ 50W<br>・同時に稼働する機器のみをカウントします。夜間は通常エアコン＋冷蔵庫＋照明、日中はテレビ等を追加<br>・上のチェックリストには一般的な値が入力済みです。実際の現場に合わせて数量と電力を調整してください。",
    "tip_load_supermarket_title": "スーパー・店舗のピーク電力の見積もり方",
    "tip_load_supermarket_body": "冷凍庫と照明が大部分を占め、多くは24時間稼働します：<br>・冷凍庫（縦型/横型）≈ 各300〜500W、ショーケース ≈ 各200〜400W。すべての台数を合計<br>・棚・通路の照明は通常メートルあたり8〜15W、一般的な棚用ライトバーは約80W。管の本数から全店の照明を合計（例：18W管 × 10本 ≈ 180W）<br>・レジ（PC＋プリンター＋キャッシュドロワー）≈ 100〜200W<br>・エアコンは営業時間中にカウント、1HP ≈ 1000W<br>・夜間も止められない冷凍庫と照明は重要負荷（Critical）としてください。",
    "tip_load_resort_title": "リゾート・ホテルのピーク電力の見積もり方",
    "tip_load_resort_body": "客室数を掛け、共用設備を加算します：<br>・1室あたり：エアコン1HP ≈ 1000W（1.5HP ≈ 1300W）＋照明100〜200W＋テレビ100W＋給湯器1500〜2000W（貯湯式）<br>・共用部：廊下・ロビーの照明は器具数から、給水ポンプ ≈ 750W、プールポンプ ≈ 1100W<br>・全室が同時に満室稼働すると仮定せず、稼働率60〜80%とし、ポンプとエアコンの稼働時間をずらしてください<br>・客室と、停電時にも止められない給水ポンプは重要負荷です。プールポンプは系統側に置けます。",
    "tip_load_cafe_title": "カフェ・レストランのピーク電力の見積もり方",
    "tip_load_cafe_body": "カフェやレストランにはデスクランプがなく、負荷は主に加熱と冷蔵です：<br>・コーヒーマシン1500〜3000W（短時間・高サージ。通常は系統側に置き、商用電源で賄います）<br>・製氷機 ≈ 800W、冷蔵庫/冷凍庫 ≈ 各200〜400W<br>・IHクッカー・電気オーブン ≈ 各2000〜4000W。ほぼ終日稼働するデリバリー中心の店舗では、同時稼働台数を合計<br>・照明はペンダント・スポットの数から、通常300〜600W<br>・業務用エアコン1.5HP ≈ 各1300W、営業時間中にカウント<br>・停電時に止められない機器（例：ほぼ終日稼働のコーヒーマシンや冷凍庫）のみ重要負荷にしてください。",
    "tip_strategy_title": "3つの戦略について",
    "tip_strategy_body": "年間平均のピーク日照時間：約4.5時間。雨季の月は平均約3時間、最悪日の単日では約2時間。乾季の月は平均約6時間、最良時で最大7時間です。<br><br><b>戦略1</b>（6時間基準・乾季平均）：乾季は十分ですが雨季は大きく不足。ROIは最高。<br><b>戦略2</b>（4.5時間基準・年平均）：乾季は余剰、雨季はやや不足。デフォルトかつ推奨。<br><b>戦略3</b>（3時間基準・雨季平均）：乾季は大幅余剰、雨季も十分。ROIは最低。",
