    "scenario_house_guide": "機器ごとに順番に確認します：エアコン、給湯器、冷蔵庫、テレビ、照明について、電力・日中の使用時間・夜間の使用時間を聞きます。冷蔵庫など常時稼働の機器は換算稼働時間を使用してください。",
    "scenario_supermarket_guide": "冷凍庫とショーケースに注目します：台数を数え、24時間稼働するか確認してください（これらは停電時にも止められない重要負荷です）。照明とエアコンは営業時間に合わせます。",
    "scenario_resort_guide": "客室ごとに確認します：エアコン、給湯器、照明に加え、給水ポンプとプールポンプ。客室の負荷と給水ポンプは通常重要負荷です。プールポンプは系統側に置けます。",
    "scenario_cafe_guide": "コーヒーマシンなど短時間・高電力の機器はデフォルトで系統側に置き（重要にチェックしない）、商用電源にサージを吸収させます。デリバリー注文でほぼ終日稼働する場合は、重要にチェックしてオフグリッド側に移し、より大きいインバーターを選択してください。",
