    "tip_backup_title": "バックアップ重要負荷",
    "tip_backup_body": "ハイブリッドモードでは、負荷を2つのグループに分けます：<br>・<b>系統側負荷</b>：インバーターが商用電源とともに給電するため、インバーター定格の制限を受けません（上記の日中/夜間負荷）。<br>・<b>バックアップ重要負荷</b>：停電時にバックアップ（EPS）ポートから給電されます。インバーターは25%の余裕を持ってこのピーク電力を賄う必要があり、複数台の並列接続で容量を拡張できます。<br>空欄にすると、全負荷を賄えるようインバーターが選定されます。",
