    "got_it": "확인",
    "tip_load_title": "최대 전력 추정 방법",
    "tip_load_body": "동시에 작동하는 모든 기기의 전력을 합산하세요:<br>· 1HP 에어컨: 최대 약 1000W<br>· 2HP 에어컨: 최대 약 2000W<br>· 컴퓨터 1대(약 200W) + 소형 냉장고(약 200W) + 조명·선풍기 몇 대(약 200W) + TV 1대(약 200W)",
    "tip_load_house_title": "가정용 최대 전력 추정 방법",
    "tip_load_house_body": "동시에 작동할 수 있는 기기를 합산하세요:<br>· 에어컨: 1HP ≈ 1000W, 1.5HP ≈ 1300W, 2HP ≈ 1800W (인버터형은 기동 돌입 전류가 더 큼)<br>· 전기 온수기 ≈ 2000W (즉석식 ≈ 6000W — 보통 오프그리드 비상 전원에 부적합)<br>· 냉장고 ≈ 150–250W, TV ≈ 100–200W, LED 조명 ≈ 개당 10–20W, 선풍기 ≈ 50W<br>· 함께 작동하는 기기만 계산하고, 밤에는 보통 에어컨 + 냉장고 + 조명, 낮에는 TV 등을 추가합니다<br>· 위 체크리스트에는 대표적인 값이 미리 입력되어 있으니 실제 현장에 맞게 수량과 전력을 조정하세요.",
    "tip_load_supermarket_title": "슈퍼마켓/매장 최대 전력 추정 방법",
    "tip_load_supermarket_body": "냉동기와 조명이 대부분이며 하루 24시간 작동하는 경우가 많습니다:<br>· 냉동고(가로/세로형) ≈ 대당 300–500W, 진열 쇼케이스 ≈ 대당 200–400W — 전체 대수를 합산<br>· 선반/통로 조명은 미터당 보통 8–15W이며, 일반적인 선반 라이트바는 약 80W입니다. 형광등 개수로 매장 전체 조명을 합산하세요 (예: 18W 등관 10개 ≈ 180W)<br>· 계산대(PC + 프린터 + 금전함) ≈ 100–200W<br>· 영업 시간 중 에어컨은 1HP ≈ 1000W로 계산<br>· 밤새 켜져 있어야 하는 냉동기와 조명은 필수 부하(critical)로 표시하세요.",
    "tip_load_resort_title": "리조트/호텔 최대 전력 추정 방법",
    "tip_load_resort_body": "객실 수를 곱한 뒤 공용 설비를 더하세요:<br>· 객실당: 에어컨 1HP ≈ 1000W (1.5HP ≈ 1300W) + 조명 100–200W + TV 100W + 온수기 1500–2000W (저장식)<br>· 공용 구역: 복도/로비 조명은 등기구 수로 계산, 급수 펌프 ≈ 750W, 수영장 펌프 ≈ 1100W<br>· 모든 객실이 동시에 사용 중이라고 가정하지 마세요 — 60~80%의 객실 점유율을 적용하고 펌프와 에어컨 가동 시간을 분산하세요<br>· 객실 부하와 정전 시에도 반드시 작동해야 하는 급수 펌프는 필수 부하이며, 수영장 펌프는 전력망 측에 둘 수 있습니다.",
    "tip_load_cafe_title": "카페/식당 최대 전력 추정 방법",
    "tip_load_cafe_body": "카페와 식당에는 데스크 조명이 없고 부하는 대부분 가열·냉장 기기입니다:<br>· 커피 머신 1500–3000W (짧고 돌입 전류가 큼 — 보통 전력망 측에 두어 상용 전원이 감당하게 함)<br>· 제빙기 ≈ 800W, 냉장고/냉동고 각 200–400W<br>· 인덕션/전기 오븐 각 2000–4000W; 거의 하루 종일 작동하는 배달 중심 매장이라면 동시 작동 대수를 합산<br>· 조명은 펜던트/스포트 개수로 계산하며 보통 300–600W<br>· 업소용 에어컨 1.5HP ≈ 대당 1300W, 영업 시간 중 계산<br>· 정전 중에도 멈출 수 없는 기기(예: 거의 항상 켜져 있는 커피 머신이나 냉동고)만 필수 부하로 지정하세요.",
    "tip_strategy_title": "세 가지 전략 소개",
    "tip_strategy_body": "연평균 일일 햇빛 시간: 약 4.5시간. 우기 월평균은 약 3시간, 최악의 하루는 약 2시간입니다. 건기 월평균은 약 6시간, 최대 7시간까지 가능합니다.<br><br><b>옵션 1</b> — 6시간 기준(건기 평균): 건기에는 충분하지만 우기에는 크게 부족하며, ROI가 가장 높습니다.<br><b>옵션 2</b> — 4.5시간 기준(연평균): 건기에는 잉여, 우기에는 약간 부족합니다. 기본값이며 추천 옵션입니다.<br><b>옵션 3</b> — 3시간 기준(우기 평균): 건기에는 잉여가 크고 우기에도 충분하지만, ROI가 가장 낮습니다.",
