    "scenario_house_guide": "에어컨, 온수기, 냉장고, TV, 조명 등 각 가전제품을 하나씩 확인하세요 — 전력, 주간 사용 시간, 야간 사용 시간. 냉장고처럼 항상 켜져 있는 기기는 환산 가동 시간을 사용하세요.",
    "scenario_supermarket_guide": "냉동고와 진열 냉장고에 집중하세요: 대수를 세고 24시간 작동하는지 확인하세요(정전 중에도 켜져 있어야 하는 필수 부하입니다). 조명과 에어컨은 영업 시간에 맞춰 계산합니다.",
    "scenario_resort_guide": "객실별로 확인하세요: 에어컨, 온수기, 조명 외에 급수 펌프와 수영장 펌프도 포함합니다. 객실 부하와 급수 펌프는 보통 필수 부하이며, 수영장 펌프는 전력망 측에 둘 수 있습니다.",
    "scenario_cafe_guide": "커피 머신 같은 짧은 고전력 기기는 기본적으로 전력망 측에 두세요(필수 부하 미체크). 이렇게 하면 상용 전원이 돌입 전류를 감당합니다. 배달 주문으로 기기가 거의 하루 종일 작동한다면 필수 부하로 체크하여 오프그리드 측으로 옮기고, 더 큰 인버터를 선택하세요.",
