    "invalid_night_hours": "야간 사용 시간은 0~16시간이어야 합니다 (16:00~8:00)",
    "selected_inverter_mode_mismatch": "선택한 인버터 모드가 케이스와 일치하지 않습니다",
    "backup_peak_power": "비상 필수 부하 최대 전력 (W)",
    "tip_backup_title": "비상 필수 부하",
    "tip_backup_body": "하이브리드 모드에서는 부하가 두 그룹으로 나뉩니다:<br>· <b>전력망 측 부하</b> — 인버터와 상용 전원이 함께 공급하므로 인버터 정격의 제한을 받지 않습니다(위의 주간/야간 부하).<br>· <b>비상 필수 부하</b> — 정전 시 백업(EPS) 포트에서 공급되며, 인버터 뱅크가 25% 여유를 두고 이 부하의 최대 전력을 감당해야 합니다. 인버터를 여러 대 병렬 연결하여 용량을 늘릴 수 있습니다.<br>모든 부하 기준으로 인버터 용량을 산정하려면 비워 두세요.",
    "invalid_backup_peak_power": "유효한 비상 필수 부하 최대 전력을 입력해 주세요",
    "no_inverter_fit": "필요 전력을 감당할 수 있는 판매 중인 인버터가 없습니다: 25% 여유를 포함해 {need_kw} kW가 필요하며, 최대 병렬 대수로도 부족합니다. 부하를 줄이거나 영업팀에 문의해 주세요.",
    "no_battery_fit": "최대 {max_qty}개 병렬 범위 내에서 필요 용량(약 {need_kwh} kWh)을 충족할 수 있는 판매 중인 배터리가 없습니다. 야간 소비 전력이나 비상 운전 일수를 줄여 주세요.",
    "no_panel_fit": "최대 {max_qty}장 범위 내에서 필요 어레이(약 {need_kw} kW)를 충족할 수 있는 판매 중인 태양광 패널이 없습니다.",
    "invalid_panel_qty": "패널 수량은 1~200 사이의 정수여야 합니다.",
    "panel_qty_string_mismatch": "모든 스트링은 같은 수의 패널을 포함해야 합니다. 균등하게 나누어지는 수량을 선택하세요.",
    "panel_string_limit_exceeded": "{qty}장의 패널이 스트링 한계를 초과합니다: 스트링당 최대 {max_series}장(모듈 Voc {module_voc}V, MPPT 최대 {mppt_voltage}V), 병렬 스트링 최대 {max_strings}개(모듈 Isc {module_isc}A, MPPT 최대 {mppt_current}A × {mppt_channels}입력). 스트링 길이가 동일한 {max_qty}장 이하로 선택해 주세요.",
    "no_panel_string_fit": "스트링 규칙(스트링당 패널 수 동일, 스트링 Voc이 MPPT 전압 한계 이내, 병렬 전류가 MPPT 전류 한계 이내)을 만족하면서 필요 어레이(약 {need_kw} kW)를 수용할 수 있는 판매 중인 인버터가 없습니다. 영업팀에 문의해 주세요.",
