    "note_hybrid_backup": "하이브리드 모드: 인버터는 비상 필수 부하(25% 여유 포함)를 기준으로 산정되며, 전력망 측 부하는 상용 전원과 함께 감당하므로 인버터 정격의 제한을 받지 않습니다.",
