    "got_it": "รับทราบ",
    "tip_load_title": "วิธีประมาณกำลังโหลดสูงสุด",
    "tip_load_body": "รวมกำลังของอุปกรณ์ทั้งหมดที่ทำงานพร้อมกัน:<br>· แอร์ 1HP: ~1000W<br>· แอร์ 2HP: ~2000W<br>· คอมพิวเตอร์ 1 เครื่อง (~200W) + ตู้เย็นเล็ก 1 ตู้ (~200W) + ไฟและพัดลมหลายดวง (~200W) + ทีวี 1 เครื่อง (~200W)",
    "tip_load_house_title": "วิธีประมาณกำลังโหลดสูงสุดของบ้าน",
    "tip_load_house_body": "รวมอุปกรณ์ที่อาจทำงานพร้อมกัน:<br>· แอร์: 1HP ≈ 1000W, 1.5HP ≈ 1300W, 2HP ≈ 1800W (แอร์อินเวอร์เตอร์มีกระแสสตาร์ตสูงกว่า)<br>· เครื่องทำน้ำอุ่นไฟฟ้า ≈ 2000W (แบบทันที ≈ 6000W — โดยทั่วไปไม่เหมาะกับระบบสำรองไฟออฟกริด)<br>· ตู้เย็น ≈ 150–250W, ทีวี ≈ 100–200W, หลอด LED ≈ 10–20W ต่อดวง, พัดลม ≈ 50W<br>· นับเฉพาะอุปกรณ์ที่ทำงานพร้อมกัน กลางคืนมักเป็นแอร์ + ตู้เย็น + ไฟฟ้าแสงสว่าง กลางวันเพิ่มทีวี ฯลฯ<br>· รายการตรวจสอบข้างต้นเติมค่าทั่วไปไว้ให้แล้ว — ปรับจำนวนและกำลังตามหน้างานจริง",
    "tip_load_supermarket_title": "วิธีประมาณกำลังโหลดสูงสุดของซูเปอร์มาร์เก็ต / ร้านค้า",
    "tip_load_supermarket_body": "ตู้แช่แข็งและไฟฟ้าแสงสว่างคือส่วนใหญ่ และมักทำงาน 24 ชม.:<br>· ตู้แช่แข็งแบบหีบ/แบบตั้ง ≈ 300–500W ต่อตู้ ตู้แสดงสินค้า ≈ 200–400W ต่อตู้ — รวมทุกตู้<br>· ไฟชั้นวางสินค้า/ทางเดินมักใช้ 8–15W ต่อเมตร ไฟเส้นชั้นวางทั่วไปประมาณ 80W รวมไฟทั้งร้านตามจำนวนหลอด (เช่น หลอด 18W จำนวน 10 ดวง ≈ 180W)<br>· จุดเก็บเงิน (คอมพิวเตอร์ + เครื่องพิมพ์ + ลิ้นชักเก็บเงิน) ≈ 100–200W<br>· เครื่องปรับอากาศนับเฉพาะเวลาเปิดร้าน 1HP ≈ 1000W<br>· ตู้แช่แข็งและไฟที่ต้องเปิดค้างคืนควรทำเครื่องหมายเป็นโหลดวิกฤต",
    "tip_load_resort_title": "วิธีประมาณกำลังโหลดสูงสุดของรีสอร์ต / โรงแรม",
    "tip_load_resort_body": "คูณด้วยจำนวนห้อง แล้วบวกอุปกรณ์พื้นที่ใช้ร่วม:<br>· ต่อห้อง: แอร์ 1HP ≈ 1000W (1.5HP ≈ 1300W) + ไฟฟ้าแสงสว่าง 100–200W + ทีวี 100W + เครื่องทำน้ำอุ่น 1500–2000W (แบบต้นเก็บ)<br>· พื้นที่ใช้ร่วม: ไฟทางเดิน/ล็อบบี้นับตามจำนวนขดไฟ ปั๊มน้ำ ≈ 750W ปั๊มสระว่ายน้ำ ≈ 1100W<br>· อย่าคิดว่าทุกห้องมีแขกพักและอุปกรณ์ทำงานพร้อมกัน — ใช้อัตราเข้าพัก 60%–80% และเว้นช่วงเวลาการทำงานของปั๊มน้ำกับแอร์<br>· ห้องแขกและปั๊มน้ำที่ต้องทำงานต่อแม้ไฟดับเป็นโหลดวิกฤต ส่วนปั๊มสระว่ายน้ำอยู่ฝั่งไฟฟ้ารัฐได้",
    "tip_load_cafe_title": "วิธีประมาณกำลังโหลดสูงสุดของคาเฟ่ / ร้านอาหาร",
    "tip_load_cafe_body": "คาเฟ่และร้านอาหารไม่มีโคมไฟตั้งโต๊ะ โหลดส่วนใหญ่คือเครื่องทำความร้อนและทำความเย็น:<br>· เครื่องชงกาแฟ 1500–3000W (ใช้เวลาสั้น กระแสสตาร์ตสูง — โดยทั่วไปอยู่ฝั่งไฟฟ้ารัฐเพื่อให้ไฟฟ้ารับภาระส่วนนี้)<br>· เครื่องทำน้ำแข็ง ≈ 800W ตู้เย็น/ตู้แช่ 200–400W ต่อตู้<br>· เตาแม่เหล็กไฟฟ้า/เตาอบไฟฟ้า 2000–4000W ต่อเครื่อง หากร้านเน้นเดลิเวอรีและใช้แทบทั้งวัน ให้รวมจำนวนเครื่องที่ทำงานพร้อมกัน<br>· ไฟฟ้าแสงสว่างนับตามจำนวนโคมห้อย/สปอตไลท์ โดยทั่วไป 300–600W<br>· แอร์เชิงพาณิชย์ 1.5HP ≈ 1300W ต่อเครื่อง นับเฉพาะเวลาเปิดร้าน<br>· เฉพาะอุปกรณ์ที่หยุดทำงานไม่ได้ระหว่างไฟดับ (เช่น เครื่องชงกาแฟหรือตู้แช่ที่เปิดแทบตลอด) ควรเป็นโหลดวิกฤต",
    "tip_strategy_title": "เกี่ยวกับกลยุทธ์ทั้งสามแบบ",
    "tip_strategy_body": "ค่าเฉลี่ยชั่วโมงแดดจัดต่อวันทั้งปี: ~4.5 ชม. ช่วงฤดูฝนเฉลี่ยเพียง ~3 ชม. วันที่แย่ที่สุด ~2 ชม. ช่วงฤดูแล้งเฉลี่ย ~6 ชม. วันที่ดีที่สุดสูงถึง 7 ชม.<br><br><b>ตัวเลือกที่ 1</b> — ออกแบบที่ 6 ชม. (ค่าเฉลี่ยฤดูแล้ง): เพียงพอในฤดูแล้ง ขาดแคลนอย่างมากในฤดูฝน ผลตอบแทนสูงสุด<br><b>ตัวเลือกที่ 2</b> — ออกแบบที่ 4.5 ชม. (ค่าเฉลี่ยทั้งปี): เหลือเกินในฤดูแล้ง ขาดเล็กน้อยในฤดูฝน ค่าเริ่มต้นและแนะนำ<br><b>ตัวเลือกที่ 3</b> — ออกแบบที่ 3 ชม. (ค่าเฉลี่ยฤดูฝน): เหลือเกินมากในฤดูแล้ง เพียงพอในฤดูฝน ผลตอบแทนต่ำสุด",
