    "scenario_house_guide": "ถามถึงเครื่องใช้ไฟฟ้าทีละเครื่อง — แอร์ เครื่องทำน้ำอุ่น ตู้เย็น ทีวี ไฟฟ้าแสงสว่าง: กำลัง ชั่วโมงใช้กลางวัน ชั่วโมงใช้กลางคืน อุปกรณ์ที่เปิดตลอดเวลาเช่นตู้เย็นให้ใช้ชั่วโมงการทำงานเทียบเท่า",
    "scenario_supermarket_guide": "เน้นตู้แช่แข็งและตู้แสดงสินค้าแช่เย็น: นับจำนวนและถามว่าทำงาน 24 ชม. หรือไม่ (เหล่านี้เป็นโหลดวิกฤตที่ต้องทำงานต่อระหว่างไฟดับ) ไฟฟ้าแสงสว่างและแอร์นับตามเวลาเปิดร้าน",
    "scenario_resort_guide": "ถามทีละห้อง: แอร์ เครื่องทำน้ำอุ่น ไฟฟ้าแสงสว่าง รวมถึงปั๊มน้ำและปั๊มสระว่ายน้ำ โหลดห้องแขกและปั๊มน้ำมักเป็นโหลดวิกฤต ส่วนปั๊มสระว่ายน้ำอยู่ฝั่งไฟฟ้ารัฐได้",
    "scenario_cafe_guide": "อุปกรณ์กำลังสูงที่ใช้เวลาสั้น เช่น เครื่องชงกาแฟ ให้อยู่ฝั่งไฟฟ้ารัฐโดยค่าเริ่มต้น (ไม่ติ๊กวิกฤต) เพื่อให้ไฟฟ้ารัฐรับกระแสสตาร์ต หากออเดอร์เดลิเวอรีทำให้เครื่องทำงานแทบทั้งวัน ให้ติ๊กวิกฤตและย้ายไปฝั่งออฟกริด แล้วเลือกอินเวอร์เตอร์ที่ใหญ่ขึ้น",
