    "tip_backup_title": "โหลดวิกฤตสำรอง",
    "tip_backup_body": "ในโหมดไฮบริด โหลดจะแบ่งเป็นสองกลุ่ม:<br>· <b>โหลดฝั่งไฟฟ้ารัฐ</b> — จ่ายไฟโดยอินเวอร์เตอร์ร่วมกับไฟฟ้ารัฐ จึงไม่ถูกจำกัดด้วยกำลังของอินเวอร์เตอร์ (โหลดกลางวัน/กลางคืนด้านบน)<br>· <b>โหลดวิกฤตสำรอง</b> — จ่ายไฟจากพอร์ตสำรอง (EPS) ระหว่างไฟดับ ชุดอินเวอร์เตอร์ต้องรองรับกำลังสูงสุดของโหลดเหล่านี้โดยเผื่อไว้ 25% และต่ออินเวอร์เตอร์หลายเครื่องขนานกันเพื่อเพิ่มกำลังได้<br>เว้นว่างไว้เพื่อออกแบบอินเวอร์เตอร์ตามโหลดทั้งหมด",
    "invalid_backup_peak_power": "กรุณากรอกกำลังสูงสุดของโหลดวิกฤตสำรองให้ถูกต้อง",
    "no_inverter_fit": "ไม่มีอินเวอร์เตอร์ที่วางขายรองรับกำลังที่ต้องการได้: ต้องการ {need_kw} kW (รวมเผื่อ 25%) แม้ต่อขนานถึงจำนวนสูงสุดแล้ว กรุณาลดโหลดหรือติดต่อฝ่ายขาย",
    "no_battery_fit": "ไม่มีแบตเตอรี่ที่วางขายรองรับความจุที่ต้องการ (~{need_kwh} kWh) ได้ภายในขีดจำกัด {max_qty} ลูกที่ต่อขนานกันได้ กรุณาลดการใช้ไฟกลางคืนหรือวันสำรองไฟ",
    "no_panel_fit": "ไม่มีแผงโซลาร์ที่วางขายรองรับแผงที่ต้องการ (~{need_kw} kW) ได้ภายในขีดจำกัด {max_qty} แผง",
    "invalid_panel_qty": "จำนวนแผงต้องเป็นจำนวนเต็มระหว่าง 1 ถึง 200",
    "panel_qty_string_mismatch": "สตริงทุกสายต้องมีจำนวนแผงเท่ากัน กรุณาเลือกจำนวนที่แบ่งเป็นสตริงเท่า ๆ กันได้",
    "panel_string_limit_exceeded": "แผง {qty} แผงเกินขีดจำกัดของสตริง: สูงสุด {max_series} แผงต่อสตริง (Voc ของแผง {module_voc}V, MPPT สูงสุด {mppt_voltage}V) สตริงขนานสูงสุด {max_strings} สาย (Isc ของแผง {module_isc}A, MPPT สูงสุด {mppt_current}A × {mppt_channels} อินพุต) กรุณาเลือกไม่เกิน {max_qty} แผงโดยแต่ละสตริงมีจำนวนแผงเท่ากัน",
    "no_panel_string_fit": "ไม่มีอินเวอร์เตอร์ที่วางขายรองรับแผงที่ต้องการ (~{need_kw} kW) ได้ภายใต้กฎของสตริง: จำนวนแผงต่อสตริงเท่ากัน Voc ของสตริงอยู่ในขีดจำกัดแรงดัน MPPT และกระแสขนานอยู่ในขีดจำกัดกระแส MPPT กรุณาติดต่อฝ่ายขาย",
    "no_voltage_match": "ไม่มีแบตเตอรี่ที่วางขายตรงกับแรงดันแบตเตอรี่ของอินเวอร์เตอร์ที่เหมาะสมเลย",
    "battery_less_inverter_out_of_stock": "ขณะนี้ไม่มีอินเวอร์เตอร์ไฮบริดแบบสตาร์ตโดยไม่ใช้แบตเตอรี่ในคลังสินค้า กรุณายืนยันกับทีมขายว่าสินค้าจะถึงเมื่อใด",
    "no_battery_less_inverter": "ไม่มีอินเวอร์เตอร์ไฮบริดในแคตตาล็อกที่รองรับการสตาร์ตโดยไม่ใช้แบตเตอรี่ จึงต้องมีแบตเตอรี่",
