    "got_it": "Đã hiểu",
    "tip_load_title": "Cách ước tính công suất đỉnh",
    "tip_load_body": "Cộng tổng công suất các thiết bị chạy đồng thời:<br>· Máy lạnh 1HP: công suất đỉnh ~1000W<br>· Máy lạnh 2HP: công suất đỉnh ~2000W<br>· Một máy tính (~200W) + một tủ lạnh nhỏ (~200W) + vài bóng đèn và một quạt (~200W) + một TV (~200W)",
    "tip_load_house_title": "Cách ước tính công suất đỉnh của hộ gia đình",
    "tip_load_house_body": "Cộng các thiết bị có thể chạy đồng thời:<br>· Máy lạnh: 1HP ≈ 1000W, 1.5HP ≈ 1300W, 2HP ≈ 1800W (máy inverter có dòng khởi động cao hơn)<br>· Máy nước nóng điện ≈ 2000W (loại tức thời ≈ 6000W — thường không phù hợp để dự phòng off-grid)<br>· Tủ lạnh ≈ 150–250W, TV ≈ 100–200W, đèn LED ≈ 10–20W mỗi bóng, quạt ≈ 50W<br>· Chỉ tính thiết bị chạy cùng lúc; ban đêm thường là máy lạnh + tủ lạnh + đèn, ban ngày thêm TV v.v.<br>· Danh sách kiểm tra ở trên đã được điền sẵn giá trị điển hình — hãy điều chỉnh số lượng và công suất theo thực tế địa điểm.",
    "tip_load_supermarket_title": "Cách ước tính công suất đỉnh siêu thị / cửa hàng",
    "tip_load_supermarket_body": "Tủ đông và chiếu sáng chiếm tỷ trọng lớn và thường chạy 24/7:<br>· Tủ đông đứng/ngang ≈ 300–500W mỗi chiếc, tủ trưng bày ≈ 200–400W mỗi chiếc — cộng tổng tất cả các máy<br>· Chiếu sáng kệ/lối đi thường 8–15W mỗi mét; dải đèn kệ thông dụng khoảng 80W. Tính tổng chiếu sáng toàn cửa hàng theo số bóng (VD: 10 × bóng 18W ≈ 180W)<br>· Quầy thu ngân (máy tính + máy in + két tiền) ≈ 100–200W<br>· Máy lạnh tính trong giờ kinh doanh, 1HP ≈ 1000W<br>· Tủ đông và đèn phải bật qua đêm cần được đánh dấu là tải trọng yếu.",
    "tip_load_resort_title": "Cách ước tính công suất đỉnh khu nghỉ dưỡng / khách sạn",
    "tip_load_resort_body": "Nhân với số phòng rồi cộng thiết bị dùng chung:<br>· Mỗi phòng: máy lạnh 1HP ≈ 1000W (1.5HP ≈ 1300W) + chiếu sáng 100–200W + TV 100W + máy nước nóng 1500–2000W (loại chứa nóng)<br>· Khu vực chung: chiếu sáng hành lang/sảnh theo số đèn, máy bơm nước ≈ 750W, máy bơm hồ bơi ≈ 1100W<br>· Đừng giả định mọi phòng đều có khách và cùng chạy — hãy dùng tỷ lệ lấp đầy 60%–80% và bố trí lệch thời gian máy bơm và máy lạnh<br>· Phòng khách và máy bơm nước phải hoạt động khi mất điện là tải trọng yếu; máy bơm hồ bơi có thể để phía lưới.",
    "tip_load_cafe_title": "Cách ước tính công suất đỉnh quán cà phê / nhà hàng",
    "tip_load_cafe_body": "Quán cà phê và nhà hàng không có đèn bàn; tải chủ yếu là thiết bị gia nhiệt và làm lạnh:<br>· Máy pha cà phê 1500–3000W (ngắn, dòng khởi động cao — thường để phía lưới để điện lưới chịu tải)<br>· Máy làm đá ≈ 800W; tủ lạnh/tủ đông 200–400W mỗi chiếc<br>· Bếp từ / lò nướng điện 2000–4000W mỗi chiếc; với quán giao hàng chạy gần như cả ngày, hãy cộng số máy chạy đồng thời<br>· Chiếu sáng theo số đèn treo/đèn điểm, thường 300–600W<br>· Máy lạnh thương mại 1.5HP ≈ 1300W mỗi chiếc, tính trong giờ kinh doanh<br>· Chỉ thiết bị không thể dừng khi mất điện (VD: máy pha cà phê hoặc tủ đông chạy gần như liên tục) mới nên là tải trọng yếu.",
    "tip_strategy_title": "Về ba chiến lược",
    "tip_strategy_body": "Giờ nắng đỉnh trung bình mỗi ngày trong năm: ~4.5h. Các tháng mùa mưa chỉ trung bình ~3h, ngày xấu nhất ~2h. Các tháng mùa khô trung bình ~6h, ngày đẹp nhất lên tới 7h.<br><br><b>Phương án 1</b> — tính theo 6h (trung bình mùa khô): đủ dùng trong mùa khô, thiếu hụt nghiêm trọng trong mùa mưa, ROI cao nhất.<br><b>Phương án 2</b> — tính theo 4.5h (trung bình cả năm): dư trong mùa khô, hơi thiếu trong mùa mưa. Mặc định và được khuyến nghị.<br><b>Phương án 3</b> — tính theo 3h (trung bình mùa mưa): dư nhiều trong mùa khô, đủ dùng trong mùa mưa, ROI thấp nhất.",
    "my_cases": "Công trình của tôi",
