    "scenario_resort": "Khu nghỉ dưỡng / Khách sạn",
    "scenario_cafe": "Quán cà phê / Nhà hàng",
    "scenario_house_guide": "Hỏi lần lượt từng thiết bị — máy lạnh, máy nước nóng, tủ lạnh, TV, chiếu sáng: công suất, giờ dùng ban ngày, giờ dùng ban đêm. Với thiết bị luôn chạy như tủ lạnh, dùng giờ chạy tương đương.",
    "scenario_supermarket_guide": "Tập trung vào tủ đông và tủ trưng bày: đếm số lượng và hỏi có chạy 24h không (đây là tải trọng yếu phải hoạt động khi mất điện). Chiếu sáng và máy lạnh theo giờ kinh doanh.",
    "scenario_resort_guide": "Hỏi từng phòng: máy lạnh, máy nước nóng, chiếu sáng, cộng thêm máy bơm nước và máy bơm hồ bơi. Tải phòng khách và máy bơm nước thường là tải trọng yếu; máy bơm hồ bơi có thể để phía lưới.",
    "scenario_cafe_guide": "Thiết bị công suất cao thời gian ngắn như máy pha cà phê mặc định để phía lưới (không đánh dấu tải trọng yếu) để điện lưới chịu dòng khởi động. Nếu đơn giao hàng khiến máy chạy gần như cả ngày, hãy đánh dấu tải trọng yếu và chuyển sang phía off-grid, rồi chọn inverter công suất lớn hơn.",
