    "selected_inverter_mode_mismatch": "Chế độ của inverter đã chọn không khớp với công trình",
    "backup_peak_power": "Công suất đỉnh tải trọng yếu dự phòng (W)",
    "tip_backup_title": "Tải trọng yếu dự phòng",
    "tip_backup_body": "Ở chế độ hybrid, tải được chia thành hai nhóm:<br>· <b>Tải phía lưới</b> — được inverter cấp điện cùng với điện lưới, nên KHÔNG bị giới hạn theo định mức inverter (các tải ngày/đêm ở trên).<br>· <b>Tải trọng yếu dự phòng</b> — được cấp điện từ cổng dự phòng (EPS) khi mất điện; bộ inverter phải đáp ứng công suất đỉnh của chúng với biên dự phòng 25%, và có thể ghép song song nhiều inverter để mở rộng công suất.<br>Để trống để tính công suất inverter cho toàn bộ tải.",
